import { AppManagementError, importMediaFile, installApk } from "./app-management.js";
import { MultipartUploadError, stageMultipartUpload } from "./multipart-upload.js";
import { HttpBodyError } from "./request-body.js";
import { UploadManager, UploadManagerError } from "./upload-manager.js";
const DEFAULT_MAX_APK_UPLOAD_BYTES = 512 * 1024 * 1024;
const DEFAULT_MAX_MEDIA_UPLOAD_BYTES = 1024 * 1024 * 1024;
const DEFAULT_MAX_ACTIVE_UPLOADS = 2;
const DEFAULT_MAX_QUEUED_UPLOADS = 4;
const DEFAULT_UPLOAD_QUEUE_TIMEOUT_MS = 5_000;
const MULTIPART_BODY_OVERHEAD_BYTES = 1024 * 1024;
function uploadLimit(value, fallback, name, allowZero = false) {
    const resolved = value ?? fallback;
    if (!Number.isSafeInteger(resolved) || resolved < (allowZero ? 0 : 1)) {
        throw new TypeError(`${name} must be ${allowZero ? "a non-negative" : "a positive"} safe integer`);
    }
    return resolved;
}
function uploadErrorResponse(error) {
    let status = 400;
    let code;
    if (error instanceof HttpBodyError) {
        status = error.status;
        code = error.code;
    } else if (error instanceof MultipartUploadError) {
        status = error.status;
        code = error.code;
    } else if (error instanceof UploadManagerError) {
        const mapped = {
            "queue-full": {
                status: 429,
                code: "upload-queue-full"
            },
            "queue-timeout": {
                status: 503,
                code: "upload-queue-timeout"
            },
            "upload-cancelled": {
                status: 499,
                code: "upload-cancelled"
            },
            "device-session-changed": {
                status: 409,
                code: "device-session-changed"
            },
            closed: {
                status: 503,
                code: "upload-service-closed"
            }
        };
        status = mapped[error.code].status;
        code = mapped[error.code].code;
    } else if (error instanceof AppManagementError) {
        status = error.code === "adb-timeout" ? 504 : 502;
        code = error.code;
    }
    return Response.json({
        ok: false,
        ...code ? {
            code
        } : {},
        error: error instanceof Error ? error.message : String(error)
    }, {
        status
    });
}
async function cleanupStagedFile(staged, operationError) {
    try {
        await staged.cleanup();
    } catch (cleanupError) {
        throw new MultipartUploadError("upload-cleanup-failed", "failed to clean up multipart upload", {
            cause: operationError === undefined ? cleanupError : new AggregateError([
                operationError,
                cleanupError
            ])
        });
    }
}
/**
 * Fetch-compatible multipart upload boundary for the embeddable middleware.
 * Each request is streamed into a private temporary file and owns an upload
 * manager slot through the final ADB operation and staging-file cleanup.
 */ export function createMiddlewareUploader(options, dependencies = {}) {
    const maxApkUploadBytes = uploadLimit(options.maxApkUploadBytes, DEFAULT_MAX_APK_UPLOAD_BYTES, "maxApkUploadBytes");
    const maxMediaUploadBytes = uploadLimit(options.maxMediaUploadBytes, DEFAULT_MAX_MEDIA_UPLOAD_BYTES, "maxMediaUploadBytes");
    const maxActiveUploads = uploadLimit(options.maxActiveUploads, DEFAULT_MAX_ACTIVE_UPLOADS, "maxActiveUploads");
    const maxQueuedUploads = uploadLimit(options.maxQueuedUploads, DEFAULT_MAX_QUEUED_UPLOADS, "maxQueuedUploads", true);
    const uploadQueueTimeoutMs = uploadLimit(options.uploadQueueTimeoutMs, DEFAULT_UPLOAD_QUEUE_TIMEOUT_MS, "uploadQueueTimeoutMs", true);
    const largestFileLimit = Math.max(maxApkUploadBytes, maxMediaUploadBytes);
    if (largestFileLimit > Number.MAX_SAFE_INTEGER - MULTIPART_BODY_OVERHEAD_BYTES) {
        throw new TypeError("upload byte limit is too large");
    }
    const stageUpload = dependencies.stageMultipartUpload ?? stageMultipartUpload;
    const installStagedApk = dependencies.installApk ?? installApk;
    const importStagedMedia = dependencies.importMediaFile ?? importMediaFile;
    const uploads = (dependencies.createUploadManager ?? ((managerOptions)=>new UploadManager(managerOptions)))({
        maxActive: maxActiveUploads,
        maxQueued: maxQueuedUploads,
        queueTimeoutMs: uploadQueueTimeoutMs
    });
    const context = {
        serial: options.serial,
        generation: 0
    };
    const handle = async (request, kind)=>{
        const fieldName = kind === "apk" ? "apk" : "file";
        const maxFileBytes = kind === "apk" ? maxApkUploadBytes : maxMediaUploadBytes;
        const action = kind === "apk" ? installStagedApk : importStagedMedia;
        try {
            const result = await uploads.run({
                context,
                requestSignal: request.signal
            }, async ({ signal })=>{
                const staged = await stageUpload(request, {
                    fieldName,
                    maxFileBytes,
                    maxBodyBytes: maxFileBytes + MULTIPART_BODY_OVERHEAD_BYTES,
                    signal
                });
                let operationError;
                try {
                    return await action(options.serial, staged, signal);
                } catch (error) {
                    operationError = error;
                    throw error;
                } finally{
                    await cleanupStagedFile(staged, operationError);
                }
            });
            return Response.json(result);
        } catch (error) {
            if (request.body && !request.body.locked) {
                await request.body.cancel(error).catch(()=>{});
            }
            return uploadErrorResponse(error);
        }
    };
    return {
        install: (request)=>handle(request, "apk"),
        importFile: (request)=>handle(request, "file"),
        snapshot: ()=>uploads.snapshot(),
        close: (cause)=>uploads.close(cause)
    };
}
